CREATE FUNCTION public.get_reviews(pid integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
   result JSON;
BEGIN
   SELECT json_agg(
      json_build_object(
         'review_id', ReviewId,
         'version_id', VersionId,
         'review', Review,
         'rating', Rating,
		 'predicted_label', PredictedLabel,
		 'confidence_score', ConfidenceScore,
		 'predicted_at', PredictedAt
      )
   )
   INTO result
   FROM Reviews
   WHERE ProductID = pid
     AND VersionId = (
         SELECT MAX(VersionId)
         FROM Reviews
         WHERE ProductID = pid
     );

   RETURN result;
END;
$$;


